// Des: Tests for sy-clou-sync: local first, offline queue drains, restore
// Flo: store pages locally > sync to the mock cloud > go offline > queue stays > come back > drain > restore from the pack
// I/O: mock cloud + temp db > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const hash = @import("ut-hash-dedu.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig");
const allo = std.testing.allocator;
const Rig = struct { tmpz: std.testing.TmpDir, srv: mock.Mock, cld: cmok.Mock, dirz: []u8, dbzz: sqli.Db, aren: std.heap.ArenaAllocator, syn: sync.Sync,
pub fn up(self: *Rig) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv.start(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.cld = cmok.Mock.init(allo); self.syn = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .store = self.cld.store(), .sql = self.cld.sql() }; }
pub fn down(self: *Rig) void { self.cld.deinit(); self.aren.deinit(); self.dbzz.close(); self.srv.halt(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn page(self: *Rig, path: []const u8) !pipe.Outc { var buf: [64]u8 = undefined; return pipe.pageFetc(allo, self.aren.allocator(), std.testing.io, .{}, &self.dbzz, self.dirz, self.srv.urlOf(&buf, path), true); } };
const NOWZ: i64 = 1790000000000;
test "local first: pages are queued, one sync uploads 1 pack + rows, queue empties" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.page("/p1"); _ = try rig.page("/p2"); _ = try rig.page("/p3"); try std.testing.expectEqual(@as(i64, 6), try outb.outbCont(&rig.dbzz, 0)); const now = pipe.nowMs(std.testing.io) + 1000; const res = try sync.syncRun(&rig.syn, rig.aren.allocator(), now); try std.testing.expectEqual(@as(u32, 3), res.recs); try std.testing.expectEqual(@as(u32, 3), res.files); try std.testing.expectEqual(@as(usize, 1), rig.cld.map.count()); try std.testing.expect(std.mem.startsWith(u8, res.pack, "runs/")); try std.testing.expectEqual(@as(i64, 0), try outb.outbCont(&rig.dbzz, 0)); try std.testing.expectEqual(@as(usize, 3), rig.cld.sawStmt("INTO cl_page")); try std.testing.expectEqual(@as(usize, 3), rig.cld.sawStmt("INTO cl_manif")); const again = try sync.syncRun(&rig.syn, rig.aren.allocator(), now); try std.testing.expectEqual(@as(u32, 0), again.files + again.recs); try std.testing.expectEqual(@as(usize, 1), rig.cld.map.count()); }
test "offline cloud: nothing lost, nothing burned; the first online sync drains everything" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.page("/p1"); _ = try rig.page("/p2"); rig.cld.offl = true; const now = pipe.nowMs(std.testing.io) + 1000; try std.testing.expectError(error.CloudSql, sync.syncRun(&rig.syn, rig.aren.allocator(), now)); try std.testing.expectEqual(@as(i64, 4), try outb.outbCont(&rig.dbzz, 0)); rig.cld.offl = false; const later = try sync.syncRun(&rig.syn, rig.aren.allocator(), now + 1000); try std.testing.expectEqual(@as(u32, 2), later.files); try std.testing.expectEqual(@as(u32, 2), later.recs); try std.testing.expectEqual(@as(i64, 0), try outb.outbCont(&rig.dbzz, 0)); }
test "SQL down after the pack upload: files stay queued and are retried" { var rig: Rig = undefined; try rig.up(); defer rig.down(); _ = try rig.page("/p1"); const now = pipe.nowMs(std.testing.io) + 1000; rig.cld.sqlo = true; try std.testing.expectError(error.CloudSql, sync.syncRun(&rig.syn, rig.aren.allocator(), now)); try std.testing.expectEqual(@as(i64, 2), try outb.outbCont(&rig.dbzz, 0)); rig.cld.sqlo = false; const res = try sync.syncRun(&rig.syn, rig.aren.allocator(), now + 3 * 3600000); try std.testing.expectEqual(@as(u32, 1), res.files); }
test "restore reads a page back from the cloud pack, hash checked" { var rig: Rig = undefined; try rig.up(); defer rig.down(); const out = try rig.page("/p2"); _ = try sync.syncRun(&rig.syn, rig.aren.allocator(), pipe.nowMs(std.testing.io) + 1000); var hx: hash.Hexz = undefined; @memcpy(&hx, out.hexz[0..64]); const body = try sync.restore(&rig.syn, rig.aren.allocator(), hx); try std.testing.expect(std.mem.indexOf(u8, body, "Item 2 page text") != null); const bogus = hash.hashHex("nothing"); try std.testing.expectError(error.NotFound, sync.restore(&rig.syn, rig.aren.allocator(), bogus)); }
test "hostile text goes through escaped, never raw into SQL" { var rig: Rig = undefined; try rig.up(); defer rig.down(); try inde.pageSet(&rig.dbzz, "http://a/x'; DROP TABLE cl_page;--", .{ .hexz = "aa", .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 1, .next = 2 }); try inde.recoSet(&rig.dbzz, "http://a/x'; DROP TABLE cl_page;--", .{ .hexz = "aa", .kind = "text", .body = "it's" }, 1); try outb.outbAdd(&rig.dbzz, "rec", "http://a/x'; DROP TABLE cl_page;--", 1, true); _ = try sync.syncRun(&rig.syn, rig.aren.allocator(), NOWZ); try std.testing.expect(rig.cld.sawStmt("x''; DROP TABLE cl_page;--") >= 1); try std.testing.expectEqual(@as(usize, 0), rig.cld.sawStmt("x'; DROP")); }
